#include "../../../include/imgdraw/canvas/Scene.hpp"#include "../../../include/imgdraw/canvas/ICanvas.hpp"namespace imgdraw{	Scene& Scene::operator=(Scene const& src)	{		if(this == &src)			return *this;				m_drawables.clear();		m_drawables.reserve(src.m_drawables.size());				for(auto const& drawable : src.m_drawables)			m_drawables.push_back(drawable->clone());				return *this;	}			void Scene::renderTo(ICanvas& canvas) const	{		for(auto const& drawable : m_drawables)			drawable->draw(canvas);	}}